#[allow(clippy::too_many_lines)]
pub fn entries() -> Vec<KernelRule> {
    vec![
        // ── D: dispatch — bounded widening staging + stride-respecting
        // admission (#29442). The commit carries two coupled halves: the
        // row-chunk staging budget for the F32 upcast, and the ldc
        // derivation that is exactly what makes the chunked writes legal
        // against a padded destination — which is also what WIDENS the
        // destination admission.
        KernelRule {
            rule_id: "widening-conversion-row-chunk-staging-budget".to_string(),
            gpu_concept: "A dtype-WIDENING staging conversion that feeds a library GEMM is bounded by CHUNKING ROWS against a fixed byte budget instead of materializing the whole widened intermediate, and the chunked writes derive the library call's lead dimension from the BYTE STRIDE (ldc = nb1/sizeof(float)) rather than the element count — which is precisely what widens the destination admission from fully-contiguous to contiguous-along-rows. The source law pair, verbatim: the budget is a named constexpr ('constexpr size_t max_src0_convert_size = 512ull * 1024 * 1024;'), admitted only when the widened staging exceeds it AND the budget actually splits the rows ('if (rows_per_chunk < src0->ne[1])'), the row count derives from the budget ('const int64_t rows_per_chunk = std::max<int64_t>(1, (int64_t) (max_src0_convert_size / f32_row_size));'), and each chunk re-enters the SAME impl as a row slice ('src0_chunk.data = (char *) src0->data + i01*src0->nb[1];' — the guard lives in the OUTER admission wrapper, so chunks never re-enter it: no recursion). The stride half is the enabler, verbatim: '// F32 chunks can have padding between rows to preserve the original destination stride.' with 'const int64_t ldc = nb1 / sizeof(float);' replacing the old ne0 lead dimension at all five cuBLAS call sites (the batched site takes 'ldc, ne1*ldc' for strideC), and the admission assert widens from bare contiguity to 'GGML_ASSERT(ggml_is_contiguous(dst) || (compute_type == GGML_TYPE_F32 && ggml_is_contiguous_1(dst)));' — the OLD comment ('Byte offsets and tensor dimensions are currently used in an inconsistent way for dst.' / 'As long as dst is contiguous this does not matter though.') states the pre-fix invariant the ldc derivation retires. DECISION CONTENT: (1) the budget bounds the INTERMEDIATE, not the call — the work is identical, the peak staging memory drops from O(GiB-class widening) to one budget-sized slice; (2) chunk admission is two-conjunct (staging exceeds budget AND the split is real) so small conversions keep the single-call path; (3) chunking REQUIRES stride-respect — a chunk written at its original destination offset with the old ne0 lead dimension would scatter across a padded destination, so the ldc half is not an independent cleanup, it is what makes the chunk arm legal (and the admission widening is its byproduct); (4) the chunk loop mutates SHALLOW tensor-header copies (ne[1]/data only), never a re-layout. ANTI-REGIME: the destination must be contiguous along rows (contiguous_1) — a fully strided destination still refuses; the compute path must tolerate per-chunk launches (a call whose launch overhead dominates a slice loses); do NOT chunk when the whole intermediate fits the budget. Distinct from row-independent-pass-block-bounded-scratch (A — a FIXED block size bounds fp32 PARTIALS for row-independent attention passes; this bounds a WIDENING CONVERSION's staging with a BUDGET-DERIVED row count and carries the stride-respect admission half), from chunk-encoder-submits-below-driver-limit (D — command-buffer SUBMISSIONS chunked below a driver limit; this is a staging byte budget for a library GEMM), from stream-invariant-operand-skips-staging-pipeline (A — skips the staging when the operand is stream-invariant; this keeps the conversion and BOUNDS it), from narrow-m-l1-panel-sizing (B186 — the K-extent panel formula from an L1 budget; this is the WIDENED-STAGING byte budget on the destination axis), and from ids-path-rebinds-stride-meaning (D — the hazard face of stride confusion: a constant correct on the direct path silently names a different quantity once an indirection joins; this DERIVES the lead dimension from the byte stride deliberately to admit padded destinations — the widening face, not the hazard face). Source: ggml-org/llama.cpp @ ab09ea4c148868aa4919b36e86962bf6ff2f32a7 (#29442) -- ggml/src/ggml-cuda/ggml-cuda.cu L1412-1418 (the comment + assert + ldc), L1661-1670 (budget + admission + rows_per_chunk + guard), L1674-1679 (the chunk loop), MIT. NotBenchable here (no measured numbers in-source -- the decision content is the budget/stride/admission law; the win class is peak-staging-memory + padded-dst admission, not a kernel-internal throughput arm; the kernel_opt GOAT gate is pending repo-wide anyway). Batch 206 / Plan 206. RIDER (Batch 218 / Plan 218, ggml-org/llama.cpp @ d890cc8959019be0e3527638f66a5a46118bb8b9 -- #29809 MIT, ggml/src/ggml-sycl/ggml-sycl.cpp + quants.hpp + convert.cpp, the LAZY REORDER member of this staging-budget family -- a pack-time LAYOUT transform staged per-expert against a byte cap, not a widening conversion staged per-row): the reorder splits each MXFP4 expert slice from 17-byte AoS blocks into [qs][e] planes so the nibble loads align -- 'The 17-byte AoS block leaves qs unaligned; split out, every 16-byte nibble block is aligned.' -- and the payoff is a load-width win, verbatim (vecdotq.hpp): 'each lane's two weight ints are one aligned 8-byte load (the AoS layout needed eight byte loads).' THE HAZARD LAW (this family's new face: allocation SUCCESS is not fit), verbatim (ggml-sycl.cpp): 'Experts are self-contained, so the tensor is reordered a few experts at a time through a small temporary: a whole-tensor temporary (hundreds of MB) can exceed the VRAM left on a nearly full card, and on Windows the driver then pages device memory out to host RAM instead of failing.' -- oversubscription does not refuse, it silently PAGES (WDDM promotes the overflow to host RAM), a worse failure than the alloc error this rule's budget anticipates, so the staging cap is not a peak-memory nicety but the guard against a silent 10x-class slowdown. THE BUDGET, verbatim: 'const size_t  max_chunk_bytes   = 32u << 20;' with the chunk derived 'const int64_t chunk_experts     = std::max<int64_t>(1, std::min<int64_t>(n_expert, (int64_t) (max_chunk_bytes / expert_bytes)));' -- the floor-1 chunk mirrors this rule's rows_per_chunk max(1,...): one oversized expert still reorders, one chunk at a time. THE DEGRADE ARM, verbatim: alloc failure logs 'failed to allocate %zu bytes for reorder temp buffer, skipping reorder' and returns false -- the generic (unaligned-layout) path stays; PR body: 'preserves the generic fallback for misaligned tensors.' THE ADMISSION, verbatim: 'The MXFP4 reorder kernels use 8-byte vector loads, so every expert slice must stay aligned.' -- the two-conjunct guard (nb % 16 || data % 16 -> skip) is this rule's admission shape carried to a layout transform: the fast path requires the alignment its vector loads assume, everything else falls through rather than mis-loads. THE PIPELINE NOTE, verbatim: 'the queue is in-order: each chunk's copy into tmp_buf waits for the previous chunk's kernel' -- in-order submission IS the chunk serialization; no event chain is owed until an out-of-order queue joins. THE LAZY TRIGGER + PREFILL FACE: the reorder fires at first decode use via optimized_feature.reorder dispatch, and prefill re-arms it explicitly -- 'reorder MXFP4 here as well, so prompt processing does not depend on a single-token decode having run first.' -- a lazy pack-time transform must be reachable from EVERY entry posture that consumes the layout, not only the posture that first triggered it. DECISION CONTENT: (1) self-containment is the chunking license -- experts do not overlap, so per-expert chunks preserve the transform's semantics; a transform whose units interact would need the whole-tensor temporary this cap exists to avoid; (2) the transform is IN-PLACE (copy chunk out, kernel writes the split layout back over the same bytes), so the budget bounds ONE chunk's staging regardless of tensor size; (3) the reorder is a one-time lazy cost amortized over every subsequent decode/prefill -- the B206 half (per-call staging) bounds RECURRING cost; the two members of this family bracket the two staging lifetimes; (4) the misaligned-admission uses the DATA pointer too ((uintptr_t) src0->data % 16), not only the stride -- a layout can be stride-aligned yet pointer-misaligned. ANTI-REGIME: never skip the fallback wiring when adding a fast layout path (the degrade arm IS the feature's safety); do not chunk a transform whose units share state; do not trust a successful large allocation as fit evidence on WDDM-class drivers (paging, not refusal, is the oversubscription mode). Distinct from this rule's widening-conversion member (B206 #29442 -- staging feeds a library GEMM per CALL; THIS feeds every later kernel per LAYOUT, one-time lazy), from complete-coverage-scatter-collapses-operand-to-dense (B115 -- install-time dense conversion gated on scatter coverage with LAZY eligibility when install ordering hides the gate; THIS reorders at first-use with the prefill re-arm face -- the two lazy-eligibility clauses answer different unknowables: coverage vs first-posture), from b212's stage-time repack face (B186-adjacent -- load alignment at pack time; the Batch-217 #306 rider's ENCODE-time permutation is the decode-ELIMINATION sibling: this transform aligns LOADS, that one deletes DECODES), and from quantized-stored-bytes-not-widened-patterns (B199 -- the storage-form axis; this is a storage FORM change too, but its decision content is the staging/admission law, not the wire-format law). Source: ggml-org/llama.cpp @ d890cc8959019be0e3527638f66a5a46118bb8b9 (#29809) -- ggml/src/ggml-sycl/ggml-sycl.cpp (reorder_qw_mxfp4_moe + the alignment guard + the prefill re-arm), ggml/src/ggml-sycl/quants.hpp (block_q_t<MXFP4> layout traits), ggml/src/ggml-sycl/convert.cpp (the reorder dispatch), MIT. NotBenchable here (the 1.91x/2.02x are Arc Pro B70 source-reported figures -- provenance, never a bar; the win class is load width + silent-paging avoidance, and the kernel_opt GOAT gate is pending repo-wide anyway). Batch 218 rider / Plan 218.".to_string(),
            ref_shape: "// naive: the WHOLE widened staging materializes for the library\n// call, and the call assumes a fully contiguous destination -- the lead\n// dimension is the element count, which is only correct while dst is\n// contiguous (byte strides and element counts used inconsistently)\nstruct T {\n    data: *mut u8,\n    ne: [i64; 2],\n    nb: [usize; 2], // byte strides; nb[1] > ne[0]*nb[0] == padded rows\n}\nfn nelements(t: &T) -> usize {\n    (t.ne[0] * t.ne[1]) as usize\n}\nunsafe fn mul_mat_cublas_naive(ctx: &Ctx, src0: &T, src1: &T, dst: &T) {\n    assert!(is_contiguous(dst)); // any padded destination REFUSES here\n    // the whole f32 upcast at once: GiB-class staging for a big src0\n    let staged = alloc_zeroed(nelements(src0) * SIZE_OF_F32);\n    convert_to_f32_into(src0, staged);\n    // lead dimension = ne[0]: fine only while dst is fully contiguous\n    gemm_ex(ctx, staged, src1, dst.data, dst.ne[0]);\n}".to_string(),
            opt_pattern: "// optimized: bound the widening staging by chunking ROWS against a\n// fixed byte budget, re-entering the same impl per slice; the chunked\n// writes derive the lead dimension from the BYTE STRIDE so a padded\n// destination stays legal -- which widens admission to contiguous_1\nconst MAX_SRC0_CONVERT_SIZE: usize = 512 * 1024 * 1024;\nunsafe fn mul_mat_cublas(ctx: &Ctx, src0: &T, src1: &T, dst: &T) {\n    assert!(is_contiguous(dst) || is_contiguous_1(dst));\n    // F32 chunks can have padding between rows to preserve the original\n    // destination stride: the lead dimension is nb[1]/sizeof(f32)\n    let ldc = dst.nb[1] / SIZE_OF_F32;\n    let src0_f32_size = nelements(src0) * SIZE_OF_F32;\n    let f32_row_size = (src0_f32_size / src0.ne[1] as usize) as usize;\n    let rows_per_chunk = (MAX_SRC0_CONVERT_SIZE / f32_row_size).max(1) as i64;\n    if src0_widened(src0) && src0_f32_size > MAX_SRC0_CONVERT_SIZE\n        && rows_per_chunk < src0.ne[1]\n    {\n        // chunk the ROWS: shallow header copies (ne[1]/data only), each\n        // slice re-enters the impl -- the guard lives here, so no recursion\n        let mut i01 = 0i64;\n        while i01 < src0.ne[1] {\n            let rows = rows_per_chunk.min(src0.ne[1] - i01);\n            let mut src_chunk = (*src0).clone();\n            src_chunk.ne[1] = rows;\n            src_chunk.data = src0.data.add((i01 * src0.nb[1] as i64) as usize);\n            let mut dst_chunk = (*dst).clone();\n            dst_chunk.ne[0] = rows;\n            dst_chunk.data = dst.data.add((i01 * dst.nb[0] as i64) as usize);\n            mul_mat_cublas_impl_f32(ctx, &src_chunk, src1, &dst_chunk, ldc);\n            i01 += rows_per_chunk;\n        }\n        return;\n    }\n    mul_mat_cublas_impl_f32(ctx, src0, src1, dst, ldc);\n}".to_string(),
        },

        // ── D: dispatch — the blocking-default-stream escape (#28782): a
        // blocking device op on the legacy default stream implicitly
        // serializes against every stream on the device; the fix moves the
        // op to the per-thread stream and restores the completion guarantee
        // with an explicit sync of THAT stream.
        KernelRule {
            rule_id: "per-thread-stream-blocking-op-explicit-sync".to_string(),
            gpu_concept: "A BLOCKING device op issued on the legacy default stream (cudaMemset and friends without a stream argument) implicitly serializes against EVERY blocking stream on the device -- and when several host threads issue such ops concurrently, they race on the ONE shared default stream -- so the fix is a STREAM CHOICE, not a semantics removal: issue the op on cudaStreamPerThread and then explicitly synchronize THAT stream, preserving the host-side completion guarantee the blocking form provided while the implicit device-wide serialization and the cross-thread default-stream race disappear. The source pair, verbatim: 'CUDA_CHECK(cudaMemsetAsync((char *)tensor->data + original_size, 0, padded_size - original_size, cudaStreamPerThread));' immediately followed by 'CUDA_CHECK(cudaStreamSynchronize(cudaStreamPerThread));' -- replacing the bare blocking 'CUDA_CHECK(cudaMemset((char *)tensor->data + original_size, 0, padded_size - original_size));' in the buffer-init padding path. THE HAZARD EVIDENCE IS THE CI HALF: the same commit deletes the ROCm test-backend-ops serialization carve-out ('# TODO: fix multi-threaded for ROCm' + 'args_extra=\"\"' under GG_BUILD_ROCM, commit subject 'ci : re-enable test-backend-ops -j for ROCm') -- multi-threaded buffer init was RUNNING THE RACE the default stream forced, and the per-thread stream is what makes -j safe. CONTEXT LAW: the file's other memset entry points already ran this exact pattern (memset_tensor and the buffer memset both carry cudaMemsetAsync(cudaStreamPerThread) + cudaStreamSynchronize(cudaStreamPerThread) at the parent) -- buffer-init's padding memset was the LAST blocking holdout, and it was precisely the one multi-threaded callers hit. DECISION CONTENT: (1) the explicit cudaStreamSynchronize is LOAD-BEARING -- dropping it turns a blocking op into fire-and-forget and breaks callers that read the memory on return; (2) the win is not the memset's own latency, it is the REMOVED implicit sync against all other device streams during init; (3) per-thread stream ordering still covers same-thread stream-ordered consumers. ANTI-REGIME: never for ops whose ordering must span host threads WITHOUT an explicit edge (cross-thread consumers need their own synchronization); never remove the sync to 'save' the host wait unless every consumer is stream-ordered on the same stream. Distinct from captured-graph-init-unconditional-and-stream-ordered (D -- the capture node-set completeness + stream-ordered init as a cross-CTA VISIBILITY edge under graph replay; this is stream CHOICE for a blocking op OUTSIDE capture -- the legacy-default-stream serialization class), from producer-store-evict-last-pins-cross-stream-consumer (A -- cache-eviction POLICY pinning for a cross-stream consumer; this is stream ASSIGNMENT for a blocking op), and from lone-stream-graph-replay-mode-switch (rust_perf -- execution MODE keyed on live population; this is per-op stream choice with the completion contract kept). Source: ggml-org/llama.cpp @ 51ce9c11a6f2dfa895696c0048c4333e8953b728 (#28782) -- ggml/src/ggml-cuda/ggml-cuda.cu L763-766 (the padding-memset pair at the post-commit file), ci/run.sh (the removed GG_BUILD_ROCM block), MIT. NotBenchable here (no measured numbers in-source -- the win is a SERIALIZATION removal during init, not a kernel-internal arm; the CI -j re-enable is the behavioral evidence; the kernel_opt GOAT gate is pending repo-wide anyway). Batch 206 / Plan 206.".to_string(),
            ref_shape: "// naive: buffer-init padding zeroed with the BLOCKING default-stream\n// memset -- it implicitly serializes against every stream on the device,\n// and N host threads calling init race on the ONE shared default stream\n// (the CI had to disable multi-threaded backend ops for ROCm over this)\nfn buffer_init_tensor(buf: &Buffer, t: &Tensor) -> Status {\n    let original_size = nbytes(t);\n    let padded_size = alloc_size(buf.buft, t);\n    if padded_size > original_size {\n        set_device(buf.device);\n        // blocking: legacy default stream -- device-wide implicit sync\n        check(cuda_memset(t.data.add(original_size), 0, padded_size - original_size));\n    }\n    Status::Success\n}\n// ci/run.sh: multi-threaded init serialized to -j 1 for ROCm:\n//   # TODO: fix multi-threaded for ROCm\n//   if [ ! -z ${GG_BUILD_ROCM} ]; then args_extra=\"\"; fi".to_string(),
            opt_pattern: "// optimized: the padding memset moves to the PER-THREAD stream with an\n// explicit sync of THAT stream -- the completion guarantee is preserved,\n// the implicit device-wide serialization and the cross-thread race go\n// away, and the CI re-enables -j for ROCm (the carve-out is deleted)\nfn buffer_init_tensor(buf: &Buffer, t: &Tensor) -> Status {\n    let original_size = nbytes(t);\n    let padded_size = alloc_size(buf.buft, t);\n    if padded_size > original_size {\n        set_device(buf.device);\n        check(cuda_memset_async(\n            t.data.add(original_size),\n            0,\n            padded_size - original_size,\n            Stream::PerThread,\n        ));\n        // LOAD-BEARING: restores the blocking form's \"done on return\"\n        // contract without the default stream's device-wide sync\n        check(stream_synchronize(Stream::PerThread));\n    }\n    Status::Success\n}\n// ci/run.sh: the ROCm block is GONE -- args_extra stays \"-j ${n_jobs}\".".to_string(),
        },
    ]
}
